109	    }
110	
111	    /**
112	     * Moves the claim to the status; a change its status does not allow is refused, as is settling by the user
113	     * who opened it, and any change to a claim dated in a closed period. A clerk settling a claim whose due is above
114	     * the clerk limit makes it PENDING instead, for a steward to approve or reject.
115	     */
116	    @Transactional
117	    public Claim changeStatus(String by, String sheetId, Long id, ClaimStatus next) {
118	        Claim claim = lockedClaim(sheetId, id);
119	        RollupService.Snapshot before = rollup.snapshot(sheetId);
120	        // settling is the step from OPEN; a pending claim is settled by approving it
121	        if (!claim.getStatus().canMoveTo(next) || next == ClaimStatus.PENDING
122	                || (next == ClaimStatus.SETTLED && claim.getStatus() != ClaimStatus.OPEN)
123	                || (next == ClaimStatus.OPEN && claim.getStatus() != ClaimStatus.DRAFT)) {
124	            throw new ResponseStatusException(HttpStatus.CONFLICT,
125	                    "A " + claim.getStatus() + " claim cannot become " + next + ".");
126	        }
127	        if (next == ClaimStatus.SETTLED && by.equals(claim.getOpenedBy())) {
128	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The user who opened a claim cannot settle it.");
129	        }
130	        if (next == ClaimStatus.OPEN) {
131	            number(sheetId, claim);
132	            claim.setOpenedBy(by);
133	        }
134	        Person person = person(sheetId, claim.getPersonId());
135	        String event = switch (next) {
136	            case OPEN -> "CLAIM_OPENED";
137	            case SETTLED -> "CLAIM_SETTLED";
138	            case VOID -> "CLAIM_VOIDED";
139	            case DRAFT, PENDING -> throw new IllegalStateException();
140	        };
141	        String tail = "";
142	        if (next == ClaimStatus.SETTLED) {
143	            // the due is fixed at the figure a statement bound it to, else at the rate the person's grade has in
144	            // force on the claim's date, with the late charge it has gained by today; with none it stays live
145	            BigDecimal figure = claim.isStated() && claim.getStatedDue() != null ? claim.getStatedDue()
146	                    : liveDue(sheetId, person, claim);
147	            BigDecimal fixed = claim.isCorrection() ? figure
148	                    : withLateCharge(figure, claim, sheets.load(sheetId));
149	            if (settings.aboveClerkLimit(sheetId, by, fixed)) {
150	                next = ClaimStatus.PENDING;
151	                event = "CLAIM_PENDING";
152	            } else {
153	                claim.setSettledDue(fixed);
154	                tail = " due=" + (fixed == null ? "n/a" : fixed.toPlainString());
155	            }
156	        }
157	        claim.setStatus(next);
158	        Claim saved = claims.saveAndFlush(claim);
159	        audit.recordOnCommit(record(event, by, person, saved) + tail);
160	        rollup.recordChanges(by, sheetId, before);
161	        return saved;
162	    }
163	
164	    /**
165	     * A steward approves a pending claim: it is settled, its due fixed at the live figure it shows now. Refused
166	     * unless it is pending, unless the user is a steward, for the user who opened it, and in a closed period.
167	     */
168	    @Transactional
169	    public Claim approve(String by, String sheetId, Long id) {
170	        Claim claim = pendingClaim(by, sheetId, id);
171	        if (by.equals(claim.getOpenedBy())) {
172	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The user who opened a claim cannot approve it.");
173	        }
174	        RollupService.Snapshot before = rollup.snapshot(sheetId);
175	        Person person = person(sheetId, claim.getPersonId());
176	        BigDecimal fixed = due(sheetId, person, claim);
177	        claim.setSettledDue(fixed);
178	        claim.setStatus(ClaimStatus.SETTLED);
179	        Claim saved = claims.saveAndFlush(claim);
180	        audit.recordOnCommit(record("CLAIM_APPROVED", by, person, saved) + " due="
181	                + (fixed == null ? "n/a" : fixed.toPlainString()));
182	        rollup.recordChanges(by, sheetId, before);
183	        return saved;
184	    }
185	
186	    /**
187	     * A steward rejects a pending claim with a reason: it is open again, bound again by its person's last statement
188	     * when that included it. Refused unless it is pending, unless the user is a steward, without a reason, and in a
189	     * closed period.
190	     */
191	    @Transactional
192	    public Claim reject(String by, String sheetId, Long id, String reason) {
193	        String why = reason == null ? "" : reason.strip();
194	        if (why.isEmpty()) {
195	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT, "A rejection needs a reason.");
196	        }
197	        Claim claim = pendingClaim(by, sheetId, id);
198	        RollupService.Snapshot before = rollup.snapshot(sheetId);
199	        claim.setStatus(ClaimStatus.OPEN);
200	        Claim saved = claims.saveAndFlush(claim);
201	        audit.recordOnCommit(record("CLAIM_REJECTED", by, person(sheetId, saved.getPersonId()), saved)
202	                + " reason=" + why);
203	        rollup.recordChanges(by, sheetId, before);
204	        return saved;
205	    }
206	
207	    /** The pending claim, locked, for a steward to decide; refused otherwise. */
208	    private Claim pendingClaim(String by, String sheetId, Long id) {
209	        Claim claim = lockedClaim(sheetId, id);
210	        if (claim.getStatus() != ClaimStatus.PENDING) {
211	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only a PENDING claim can be approved or rejected.");
212	        }
213	        if (!settings.isSteward(sheetId, by)) {
214	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can approve or reject a claim.");
215	        }
216	        return claim;
217	    }
218	
219	    /** The claim, locked; refused when it is dated in a closed period. */
220	    private Claim lockedClaim(String sheetId, Long id) {
221	        // the sheet is locked before the claim, in the order a period closing takes them
222	        sheets.lock(sheetId);
223	        Claim claim = claims.findWithLockByIdAndSheetId(id, sheetId)
224	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
225	        refuseInClosedPeriod(sheetId, claim.getDate());
226	        return claim;
227	    }
228	
229	    /**
230	     * Gives the claim being opened its number: while the sheet's period numbering from is set and its today is on or
231	     * after it, the next in the sequence of the period the claim is dated in (X for none), else the sheet's next.
232	     * The sheet is locked, so two claims opened at once never get the same one.
233	     */
234	    private void number(String sheetId, Claim claim) {
235	        Sheet sheet = sheets.load(sheetId);
236	        LocalDate from = sheet.getPeriodNumberingFrom();
237	        if (from == null || sheet.getToday().isBefore(from)) {
238	            claim.setNumber(String.valueOf(sheets.nextClaimNumber(sheetId)));
239	            return;
240	        }
241	        String sequence = periods.findFirstBySheetIdAndFromLessThanEqualAndToGreaterThanEqual(sheetId,
242	                claim.getDate(), claim.getDate()).map(Period::getName).orElse(NO_PERIOD);
243	        Long last = claims.lastInSequence(sheetId, sequence);
244	        claim.numberIn(sequence, last == null ? 1 : last + 1);
245	    }
246	
247	    /**
248	     * The claim's live due: at the rate its person's grade in force on its date has in force on that date, and at least the sheet's
249	     * floor (a correction has none), rounded as the sheet's policy date decides for it; null (n/a) with none.
250	     */
251	    public BigDecimal liveDue(String sheetId, Person person, Claim claim) {
252	        Sheet sheet = sheets.load(sheetId);
253	        BigDecimal floor = claim.isCorrection() ? null : sheet.getFloor();
254	        RoundingMode rounding = sheet.roundingOn(claim.getRoundsOn());
255	        return rates.findInForce(sheetId, person.gradeOn(claim.getDate()), claim.getDate()).map(Rate::getPct)
256	                .map(pct -> floored(dueOn(claim.getAmount(), pct, rounding), floor)).orElse(null);
257	    }
258	
259	    /**
260	     * The figure the claim shows and totals: its settled due, else the one a statement bound it to (not while it is
261	     * pending), else live.
262	     */
263	    public BigDecimal figure(String sheetId, Person person, Claim claim) {
264	        if (claim.getSettledDue() != null) {
265	            return claim.getSettledDue();
266	        }
267	        return claim.isBound() ? claim.getStatedDue() : liveDue(sheetId, person, claim);
268	    }
269	
270	    /**
271	     * The due the claim shows and totals: its figure, with the late charge an open (or pending) overdue claim has gained; a
272	     * correction gains none.
273	     */
274	    public BigDecimal due(String sheetId, Person person, Claim claim) {
275	        BigDecimal figure = figure(sheetId, person, claim);
276	        return claim.getStatus().isOpen() && !claim.isCorrection()
277	                ? withLateCharge(figure, claim, sheets.load(sheetId))
278	                : figure;
279	    }
280	
281	    /**
282	     * The figure (null for n/a) of the claim, with the sheet's late percent of it added for every full 30 days it is
283	     * overdue by the sheet's today, rounded like its due. The charge is never bound by a statement: it keeps
284	     * following the sheet's today and its policy date.
285	     */
286	    public static BigDecimal withLateCharge(BigDecimal figure, Claim claim, Sheet sheet) {
287	        if (figure == null || sheet == null || sheet.getToday() == null) {
288	            return figure;
289	        }
290	        long overdue = ChronoUnit.DAYS.between(claim.getDate().plusDays(sheet.getTerms()), sheet.getToday());
291	        long periods = overdue > 0 ? overdue / 30 : 0;
292	        if (periods == 0 || sheet.getLatePct().signum() == 0) {
293	            return figure;
294	        }
295	        return figure.add(dueOn(figure, sheet.getLatePct().multiply(BigDecimal.valueOf(periods)),
296	                sheet.roundingOn(claim.getRoundsOn())));
297	    }
298	
299	    /**
300	     * Refuses a change to a claim dated on the date when a closed period contains it. The sheet stays locked until
301	     * the transaction ends, so a period closing at the same moment is checked in turn.
302	     */
303	    private void refuseInClosedPeriod(String sheetId, LocalDate date) {
304	        sheets.lock(sheetId);
305	        if (periods.existsBySheetIdAndClosedTrueAndFromLessThanEqualAndToGreaterThanEqual(sheetId, date, date)) {
306	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That claim is dated in a closed period.");
307	        }
308	    }
309	
310	    /**
311	     * The number a claim with the amount corrects: for a correction (a negative amount), the number of a settled
312	     * claim of the person, else refused; null for any other claim.
313	     */
314	    private String correctedNumber(String sheetId, Long personId, BigDecimal amount, String corrects) {
315	        if (amount.signum() >= 0) {
316	            return null;
317	        }
318	        corrects = corrects == null ? null : corrects.strip();
319	        if (corrects == null || !claims.existsBySheetIdAndPersonIdAndNumberAndStatus(sheetId, personId, corrects,
320	                ClaimStatus.SETTLED)) {
321	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
322	                    "A negative amount must correct a settled claim of the person, named by its number.");
323	        }
324	        return corrects;
325	    }
326	
327	    /** Refuses a claim for the person dated after their retirement date; one on or before it is allowed. */
328	    private static void refuseAfterRetirement(Person person, LocalDate date) {
329	        if (person.getRetiredFrom() != null && date.isAfter(person.getRetiredFrom())) {
330	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
331	                    "That claim is dated after the person's retirement.");
332	        }
333	    }
334	
335	    private Person person(String sheetId, Long personId) {
336	        return people.findByIdAndSheetId(personId, sheetId)
337	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
338	    }
339	
340	    /** The audit line about a claim; one that has a number ends with it. */
341	    private static String record(String event, String by, Person person, Claim c) {
342	        String number = c.getNumber();
343	        return event + " sheet=" + c.getSheetId() + " by=" + by + " person=" + person.getName()
344	                + " amount=" + c.getAmount().toPlainString() + " date=" + c.getDate()
345	                + (number != null ? " number=" + number : "");
346	    }
347	
348	    /**
349	     * The due on an amount at a rate: amount times rate divided by 100, rounded to two decimals the given way (a
350	     * negative amount rounds like its positive).
351	     */
352	    public static BigDecimal dueOn(BigDecimal amount, BigDecimal pct, RoundingMode rounding) {
353	        return amount.multiply(pct).movePointLeft(2).setScale(2, rounding);
354	    }
355	
356	    /** The date a claim dated on the date rounds by: that date, or for a correction the corrected claim's date. */
357	    private LocalDate roundsOn(String sheetId, String corrects, LocalDate on) {
358	        return corrects == null ? on
359	                : claims.findBySheetIdAndNumber(sheetId, corrects).map(Claim::getDate).orElse(on);
360	    }
361	
362	    /** The due raised to the floor when it is below it. */
363	    public static BigDecimal floored(BigDecimal due, BigDecimal floor) {
364	        return floor != null && due.compareTo(floor) < 0 ? floor.setScale(2) : due;
365	    }
366	
367	    private LocalDate dateOrToday(String sheetId, LocalDate date) {
368	        return date != null ? date : sheets.load(sheetId).getToday();
369	    }
370	
371	    private static BigDecimal scaled(BigDecimal amount) {
372	        return amount.setScale(2, RoundingMode.UNNECESSARY);
373	    }
374	
375	    private static String noteOf(String note) {
376	        return note == null ? "" : note.strip();
377	    }
378	}
